    "hub": "Chemical Equilibrium and Electrochemical Principles",
    "major_branches": [
      {
        "title": "Chemical Equilibrium",
        "sub_concepts": [
          {
            "title": "Equilibrium Constant (Kc)",
            "details": "Ratio of product concentrations to reactant concentrations at equilibrium: Kc = [products]/[reactants]"
          },
          {
            "title": "Le Chatelier's Principle",
            "details": "A system at equilibrium will shift to oppose any applied stress (e.g., changes in concentration, temperature, pressure)"
          },
          {
            "title": "Catalysts",
            "details": "Speed up the rate at which equilibrium is reached but do not change the value of the equilibrium constant (Kc)"
          }
        ]
      },
      {
        "title": "Electrochemistry: Galvanic Cells",
        "sub_concepts": [
          {
            "title": "Cell Components and Reactions",
            "details": [
              "Anode: Site of oxidation",
              "Cathode: Site of reduction"
            ]
          },
          {
            "title": "Standard Cell Potential (EÂ°cell)",
            "details": "Calculated as the difference between the standard reduction potential of the cathode and the anode: EÂ°cell = EÂ°cathode - EÂ°anode"
          },
          {
            "title": "Nernst Equation",
            "details": "Relates the cell's electromotive force (EMF) to the concentrations of reactants and products"
          }
        ]
      }
    ]
  }
}

