  "mind_map": "# Electrical Circuit Principles",
  "branches": [
    {
      "name": "Fundamental Laws",
      "sub_concepts": [
        {
          "name": "Ohm's Law",
          "details": "V = IR (Voltage = Current Ã Resistance)"
        },
        {
          "name": "Kirchhoff's Junction Rule",
          "details": "Sum of currents entering a junction equals sum of currents leaving (Î£I_in = Î£I_out)"
        }
      ]
    },
    {
      "name": "Resistance and Resistivity",
      "sub_concepts": [
        {
          "name": "Resistivity (Ï)",
          "details": "Ï = RA/l (Resistance Ã Area / Length)"
        },
        {
          "name": "Equivalent Resistance (R_eq)",
          "sub_concepts": [
            {
              "name": "Series Circuits",
              "details": "R_eq = R1 + R2"
            },
            {
              "name": "Parallel Circuits",
              "details": "1/R_eq = 1/R1 + 1/R2"
            }
          ]
        }
      ]
    },
    {
      "name": "Current and Charge Carrier Motion",
      "sub_concepts": [
        {
          "name": "Current (I) from Drift Velocity",
          "details": "I = neAv_d (Number of charge carriers Ã elementary charge Ã Area Ã drift velocity)"
        },
        {
          "name": "Drift Velocity (v_d)",
          "details": "Average velocity of charge carriers in an electric field"
        }
      ]
    }
  ]
}

