{
  "mind_map": "# Lens Optics: Formulas and Conventions",
  "branches": [
    {
      "title": "Fundamental Lens Formula",
      "sub_concepts": [
        "Relates focal length (f), image distance (v), and object distance (u)",
        "Formula: 1/f = 1/v - 1/u"
      ]
    },
    {
      "title": "Magnification (m)",
      "sub_concepts": [
        "Ratio of image size to object size",
        "Formula: m = v/u"
      ]
    },
    {
      "title": "Power of a Lens (P)",
      "sub_concepts": [
        "Measure of a lens's ability to converge or diverge light",
        "Formula: P = 1/f",
        "Unit: Diopters (when f is in metres)"
      ]
    },
    {
      "title": "Sign Conventions",
      "sub_concepts": [
        "Real object: object distance (u) is negative"
      ]
    },
    {
      "title": "Ray Tracing Principle",
      "sub_concepts": [
        "Ray passing through the optical centre of a lens remains undeviated"
      ]
    }
  ]
}

