pred_mind_map_markdown:
{
  "mind_map": "# Fundamental Principles of Physics: Optics and Electricity",
  "branches": [
    {
      "title": "Optics: Lens Properties and Ray Tracing",
      "sub_concepts": [
        {
          "title": "Lens Formula",
          "details": "1/f = 1/v - 1/u (relates focal length, image distance, object distance)"
        },
        {
          "title": "Magnification (m)",
          "details": "m = v/u (ratio of image distance to object distance)"
        },
        {
          "title": "Lens Power (P)",
          "details": "P = 1/f (focal length 'f' in meters)"
        },
        {
          "title": "Sign Convention",
          "details": "Real object 'u' is negative"
        },
        {
          "title": "Ray Behavior",
          "details": "Ray through optical centre is undeviated"
        }
      ]
    },
    {
      "title": "Electricity: Circuits and Current Flow",
      "sub_concepts": [
        {
          "title": "Ohm's Law",
          "details": "V = IR (voltage, current, resistance relationship)"
        },
        {
          "title": "Resistivity (Ï)",
          "details": "Ï = RA/l (material property, depends on resistance, area, length)"
        },
        {
          "title": "Equivalent Resistance (R_eq)",
          "sub_concepts": [
            {
              "title": "Series Circuits",
              "details": "R_eq = R1 + R2"
            },
            {
              "title": "Parallel Circuits",
              "details": "1/R_eq = 1/R1 + 1/R2"
            }
          ]
        },
        {
          "title": "Kirchhoff's Junction Rule",
          "details": "Sum of current in = Sum of current out (conservation of charge)"
        },
        {
          "title": "Current and Drift Velocity",
          "details": "I = neAv_d (current, number density, charge, area, drift velocity)"
        }
      ]
    }
  ]
}

