          {
            "name": "Ohm's Law",
            "details": "V=IR (Voltage = Current Ã Resistance)"
          },
          {
            "name": "Resistivity",
            "details": "Ï=RA/l (Resistivity = Resistance Ã Area / Length)"
          }
        ]
      },
      {
        "title": "Equivalent Resistance Calculations",
        "concepts": [
          {
            "name": "Series Circuits",
            "details": "R_eq=R1+R2 (Equivalent Resistance = Sum of individual resistances)"
          },
          {
            "name": "Parallel Circuits",
            "details": "1/R_eq=1/R1+1/R2 (Reciprocal of Equivalent Resistance = Sum of reciprocals of individual resistances)"
          }
        ]
      },
      {
        "title": "Current Flow and Conservation",
        "concepts": [
          {
            "name": "Kirchhoff's Junction Rule",
            "details": "sum I_in = sum I_out (Sum of currents entering a junction equals sum of currents leaving)"
          },
          {
            "name": "Current from Drift Velocity",
            "details": "I=neAv_d (Current = number of charge carriers Ã elementary charge Ã cross-sectional area Ã drift velocity)"
          }
        ]
      }
    ]
  }
}

